using System.Diagnostics.CodeAnalysis;
using System.Runtime.InteropServices;
using System.Runtime.Versioning;
using Windows.Win32;
using Windows.Win32.Foundation;
using Windows.Win32.System.Com;
using Windows.Win32.UI.Accessibility;

namespace Rig.Core.Desktop.Windows.Uia;

/// <summary>
/// UI Automation through UIAutomationCore's COM API, its interop generated by CsWin32 from Windows' metadata. Every COM
/// failure surfaces as <see cref="UiaException"/>. Ported from the comtypes session in
/// <c>desktop_manager.chrome.uia_core</c>.
/// </summary>
[SupportedOSPlatform("windows8.1")]
[ExcludeFromCodeCoverage(Justification = "COM interop; the Windows CI job smoke-tests it, the ubuntu coverage run cannot reach it.")]
public sealed class NativeUiAutomation : IUiAutomation
{
    private readonly IUIAutomation _automation;
    private readonly IUIAutomationTreeWalker _control;
    private readonly IUIAutomationTreeWalker _raw;

    /// <summary>Creates the session: one per command.</summary>
    public NativeUiAutomation()
    {
        _automation = (IUIAutomation)new CUIAutomation();
        _control = _automation.ControlViewWalker;
        _raw = _automation.RawViewWalker;
    }

    /// <inheritdoc/>
    public IUiaElement? ElementFromHandle(long handle)
    {
        try
        {
            var element = _automation.ElementFromHandle(new HWND((nint)handle));
            return Wrap(element);
        }
        catch (COMException)
        {
            return null;
        }
    }

    internal NativeUiaElement? Wrap(IUIAutomationElement? element) => element is null ? null : new(this, element);

    internal IUIAutomationTreeWalker Walker(UiaView view) => view == UiaView.Raw ? _raw : _control;

    internal bool Compare(IUIAutomationElement first, IUIAutomationElement second) =>
        _automation.CompareElements(first, second);

    internal IUIAutomationCondition Condition(UiaCondition condition)
    {
        var parts = new List<IUIAutomationCondition>();
        if (condition.ControlType is { } type)
        {
            parts.Add(_automation.CreatePropertyCondition(UIA_PROPERTY_ID.UIA_ControlTypePropertyId, (int)type));
        }

        if (condition.ClassName is { } className)
        {
            parts.Add(_automation.CreatePropertyCondition(UIA_PROPERTY_ID.UIA_ClassNamePropertyId, className));
        }

        if (condition.Name is { } name)
        {
            parts.Add(_automation.CreatePropertyCondition(UIA_PROPERTY_ID.UIA_NamePropertyId, name));
        }

        if (parts.Count == 0)
        {
            return _automation.CreateTrueCondition();
        }

        var combined = parts[0];
        foreach (var part in parts.Skip(1))
        {
            combined = _automation.CreateAndCondition(combined, part);
        }

        return combined;
    }
}

/// <summary>One live element behind <see cref="NativeUiAutomation"/>.</summary>
[SupportedOSPlatform("windows8.1")]
[ExcludeFromCodeCoverage(Justification = "COM interop; the Windows CI job smoke-tests it, the ubuntu coverage run cannot reach it.")]
internal sealed unsafe class NativeUiaElement(NativeUiAutomation automation, IUIAutomationElement element) : IUiaElement
{
    private const int StaleElement = unchecked((int)0x80040201);

    public string Name => Call(() => Text(element.CurrentName));

    public string ClassName => Call(() => Text(element.CurrentClassName));

    public UiaControlType ControlType => Call(() => Enum.IsDefined((UiaControlType)element.CurrentControlType)
        ? (UiaControlType)element.CurrentControlType
        : UiaControlType.Other);

    public IReadOnlyList<int> RuntimeId => Call(() => ReadRuntimeId(element.GetRuntimeId()));

    public UiaRect BoundingRectangle => Call(() =>
    {
        var rect = element.CurrentBoundingRectangle;
        return new UiaRect(rect.left, rect.top, rect.right, rect.bottom);
    });

    public bool IsOffscreen => Call(() => (bool)element.CurrentIsOffscreen);

    public bool HasKeyboardFocus => Call(() => (bool)element.CurrentHasKeyboardFocus);

    public bool IsSelected => Call(() => (bool)Pattern<IUIAutomationSelectionItemPattern>(UIA_PATTERN_ID.UIA_SelectionItemPatternId).CurrentIsSelected);

    public IUiaElement? Parent(UiaView view = UiaView.Control) =>
        Call(() => automation.Wrap(automation.Walker(view).GetParentElement(element)));

    public IUiaElement? FirstChild(UiaView view = UiaView.Control) =>
        Call(() => automation.Wrap(automation.Walker(view).GetFirstChildElement(element)));

    public IUiaElement? NextSibling(UiaView view = UiaView.Control) =>
        Call(() => automation.Wrap(automation.Walker(view).GetNextSiblingElement(element)));

    public bool SameAs(IUiaElement other) =>
        other is NativeUiaElement native && Call(() => automation.Compare(element, native.Element));

    public IReadOnlyList<IUiaElement> FindAll(UiaScope scope, UiaCondition condition) => Call(() =>
    {
        var found = element.FindAll(Scope(scope), automation.Condition(condition));
        var elements = new List<IUiaElement>();
        if (found is null)
        {
            return elements;
        }

        for (var index = 0; index < found.Length; index++)
        {
            elements.Add(new NativeUiaElement(automation, found.GetElement(index)));
        }

        return elements;
    });

    public IUiaElement? FindFirst(UiaScope scope, UiaCondition condition) =>
        Call(() => automation.Wrap(element.FindFirst(Scope(scope), automation.Condition(condition))));

    public void SelectItem() => Call(() => Pattern<IUIAutomationSelectionItemPattern>(UIA_PATTERN_ID.UIA_SelectionItemPatternId).Select());

    public void Invoke() => Call(() => Pattern<IUIAutomationInvokePattern>(UIA_PATTERN_ID.UIA_InvokePatternId).Invoke());

    public bool Expand() => Call(() =>
    {
        if (element.GetCurrentPattern(UIA_PATTERN_ID.UIA_ExpandCollapsePatternId) is not IUIAutomationExpandCollapsePattern pattern)
        {
            return false;
        }

        pattern.Expand();
        return true;
    });

    public bool ScrollIntoView() => Call(() =>
    {
        if (element.GetCurrentPattern(UIA_PATTERN_ID.UIA_ScrollItemPatternId) is not IUIAutomationScrollItemPattern pattern)
        {
            return false;
        }

        pattern.ScrollIntoView();
        return true;
    });

    public void ShowContextMenu() => Call(() =>
    {
        if (element is not IUIAutomationElement3 element3)
        {
            throw new UiaException("The element cannot show a context menu (no IUIAutomationElement3).");
        }

        element3.ShowContextMenu();
    });

    internal IUIAutomationElement Element => element;

    private T Pattern<T>(UIA_PATTERN_ID id)
        where T : class =>
        element.GetCurrentPattern(id) as T ?? throw new UiaException($"The element has no {typeof(T).Name}.");

    private static TreeScope Scope(UiaScope scope) => scope switch
    {
        UiaScope.Children => TreeScope.TreeScope_Children,
        UiaScope.Descendants => TreeScope.TreeScope_Descendants,
        _ => TreeScope.TreeScope_Subtree,
    };

    private static string Text(BSTR text)
    {
        try
        {
            return text.ToString() ?? string.Empty;
        }
        finally
        {
            UiaNative.SysFreeString(text);
        }
    }

    private static int[] ReadRuntimeId(SAFEARRAY* array)
    {
        if (array is null)
        {
            return [];
        }

        try
        {
            UiaNative.SafeArrayGetLBound(array, 1, out var lower).ThrowOnFailure();
            UiaNative.SafeArrayGetUBound(array, 1, out var upper).ThrowOnFailure();
            var parts = new int[Math.Max(0, upper - lower + 1)];
            for (var index = lower; index <= upper; index++)
            {
                int value;
                UiaNative.SafeArrayGetElement(array, index, &value).ThrowOnFailure();
                parts[index - lower] = value;
            }

            return parts;
        }
        finally
        {
            _ = UiaNative.SafeArrayDestroy(array);
        }
    }

    private static T Call<T>(Func<T> read)
    {
        try
        {
            return read();
        }
        catch (COMException error)
        {
            throw new UiaException(
                error.HResult == StaleElement
                    ? "The element is no longer available."
                    : $"UI Automation call failed (0x{error.HResult:X8}).",
                error);
        }
        catch (InvalidCastException error)
        {
            throw new UiaException("UI Automation handed back an unexpected interface.", error);
        }
    }

    private static void Call(Action act) => Call(() =>
    {
        act();
        return true;
    });
}
